"""Optional passkey homeowner accounts; all browsing and local lists remain usable."""
import re
import shutil
from editorial import write_editorial_page


def add(out, origin, pages):
    root = out.parent
    body = '''<div class="wrap account-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Your Wazoozie</div><section class="account-intro"><div><div class="eyebrow">A PLACE FOR YOUR NEXT GOOD PROJECT.</div><h1>Your home.<br><em>Your little corner.</em></h1><p>Keep your projects and favorite local businesses together. Pick up where you left off when you sign in on another device.</p></div><aside><span aria-hidden="true">⌂</span><strong>Make yourself at home.</strong><p>Free and optional. Browse, call businesses and use the planning tools with or without an account.</p></aside></section><p id="account-status" class="account-status" role="status" aria-live="polite">Checking account availability…</p><section id="account-auth" class="account-auth" hidden><div><div class="eyebrow">NEW AROUND HERE?</div><h2>A home for your home projects.</h2><ul><li>Keep your project list across signed-in devices.</li><li>Save the businesses you want to come back to.</li><li>Move from planning to ready-to-call to finished.</li></ul><form id="account-create"><label>First name or nickname<input id="account-name" autocomplete="nickname" maxlength="60" required placeholder="What should we call you?"></label><button class="btn primary" type="submit">Create my free account →</button></form><p class="account-small">Your device will help you create a passkey using its password manager, fingerprint, face unlock or security key. Wazoozie receives a public key—not your fingerprint or face data.</p></div><div class="account-return"><div class="eyebrow">GOOD TO SEE YOU AGAIN.</div><h2>Welcome back.</h2><p>Use the passkey you saved for Wazoozie.</p><button type="button" id="account-login" class="btn primary">Sign in with a passkey →</button><details><summary>Use a recovery code</summary><form id="account-recover"><label>Your saved recovery code<input id="account-recovery-input" autocomplete="off" maxlength="100" spellcheck="false" required></label><button type="submit" class="btn outline">Recover my account</button></form></details><p class="account-small">No email or password is needed. Keep your passkey and recovery code safe: there is no email-based reset.</p><a href="/my-home/">Use a device-only list instead →</a></div></section><section id="account-recovery" class="account-recovery" hidden><h2>Keep a way back in.</h2><p>Save this recovery code somewhere private, separate from this browser. It signs you in if you lose your passkey. Each use replaces it with a new code.</p><code id="account-recovery-code"></code><button type="button" class="btn outline" id="account-copy-recovery">Copy recovery code</button><button type="button" class="btn primary" id="account-hide-recovery">I’ve saved it</button><p class="account-small">The code is shown only now. Wazoozie stores only its hash.</p></section><section id="account-dashboard" hidden><div class="account-toolbar"><div><div class="eyebrow">YOUR WAZOOZIE</div><h2 id="account-greeting">Welcome home.</h2><p id="account-summary"></p></div><button type="button" class="btn outline" id="account-logout">Sign out</button></div><div id="account-import-panel" class="account-import" hidden><div><strong>Bring your device-only list with you.</strong><p>Your saved categories and stages can be copied into this account. Existing account projects keep their current progress.</p></div><button type="button" class="btn outline" id="account-import">Import this device’s projects</button></div><div class="account-dashboard-grid"><section><h2>Your projects</h2><p id="account-empty">A repair, a refresh, a bigger idea. Add your first project below.</p><div id="account-projects" class="account-projects"></div><label class="account-add-label">Add a project<select id="account-project-choice"></select></label><button type="button" class="btn primary" id="account-add-project">Add to my projects +</button></section><aside class="account-favorites"><h2>Your local people.</h2><p>Keep the businesses you want to find again. Saving a favorite does not contact the business.</p><div id="account-businesses"></div><a href="/#find">Explore the full directory →</a></aside></div><section class="account-settings"><h2>Account & access</h2><p>Your first name or nickname, saved project categories, progress, favorite business IDs and sign-in information are stored privately. No email, phone or address is required. Nothing here books a visit or signs you up for marketing.</p><button type="button" class="btn outline" id="account-backup">Add a backup passkey</button><p id="account-key-count" class="account-small"></p><details><summary>Delete my account</summary><p>This permanently deletes your account, saved projects, favorites and Wazoozie passkey records. Your device-only list is separate. Sign in again first if asked.</p><form id="account-delete"><label>Type DELETE to confirm<input id="account-delete-confirm" autocomplete="off" required pattern="DELETE"></label><button class="btn outline" type="submit">Permanently delete my account</button></form></details></section></section><noscript><p>Accounts need JavaScript. You can still <a href="/#find">browse businesses</a> and call directly.</p></noscript><p class="account-small">Using another device? Sign in with the same passkey through your password manager or supported phone. Keep a backup passkey or recovery code if your passkey is not synced. <a href="/privacy/">Privacy details →</a></p></div>'''
    write_editorial_page(out, origin, pages, '/account/', 'Your Wazoozie | Optional homeowner account', 'Keep your saved projects, progress and favorite local businesses in your own optional Wazoozie account. Free passkey sign-in without an email or password.', body)
    pages.remove('/account/')  # Private dashboard shell does not belong in search results.
    for target in out.rglob('*.html'):
        s=target.read_text()
        s=s.replace('<a href="/my-home/">My home <span data-home-count></span></a>', '<a href="/account/">Log in / Create account</a>')
        s=s.replace('<details class="mobile-menu">', '<a class="account-top-link" href="/account/">Log in / Sign up</a><details class="mobile-menu">',1)
        s=s.replace('<nav aria-label="Mobile navigation">', '<nav aria-label="Mobile navigation"><a href="/account/">Log in / Create account</a>',1)
        s=s.replace('<strong>The useful details</strong>', '<strong>The useful details</strong><a href="/account/">Sign in / create an account</a>',1)
        if target==out/'index.html':
            marker='<section class="workbench-tools"'
            invitation='<section class="account-home-invite"><div><div class="eyebrow">A LITTLE MORE CONNECTED.</div><h2>A place to keep<br><em>your next good thing.</em></h2><p>Your projects. Your favorite local people. Ready when you come back.</p></div><div><a class="btn primary" href="/account/">Create your free account →</a><a href="/account/">Already have an account? Sign in ↗</a><small>Optional, private and passwordless.</small></div></section>'
            s=s.replace(marker,invitation+marker,1)
        if target==out/'my-home/index.html':
            s=s.replace('<div class="home-list-toolbar">','<div class="account-local-invite"><strong>Want your projects on another device?</strong><p>Create a free account, then choose to import this device’s list. Browsing and your device-only list stay available.</p><a href="/account/">Sign in or create an account →</a></div><div class="home-list-toolbar">',1)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/accounts.css"></head>',1)
        if target==out/'account/index.html':
            s=re.sub(r'<meta name="robots"[^>]*>','<meta name="robots" content="noindex,nofollow">',s,1)
            s=s.replace('</body>','<script src="/assets/passkeys.js" defer></script><script type="module" src="/assets/accounts.js"></script></body>',1)
        target.write_text(s)
    privacy=out/'privacy/index.html'
    privacy.write_text(privacy.read_text().replace('</main>','<section class="wrap project-inline"><h2>Optional homeowner accounts.</h2><p>Accounts store a first name or nickname, project categories and stages, favorite business identifiers, a recovery-code hash and public passkey credentials in private Cloudflare storage. Your biometric information stays with your device. Account data is retained until you delete the account; it is not shared with listed businesses or used to subscribe you to marketing. Sign-in challenges expire after five minutes. A secure, HttpOnly session cookie keeps you signed in for up to 14 days. Expired sessions, challenges and rate-limit records are cleaned daily. You can export your list using your browser’s print feature and permanently delete account data on Your Wazoozie. Device-only lists remain separate unless you explicitly import them. There is no email-based recovery: keep a backup passkey or your recovery code.</p></section></main>',1))
    for name in ('accounts.css','accounts.js'):
        shutil.copy(root/'assets'/name,out/'assets'/name)
    shutil.copy(root/'node_modules/@simplewebauthn/browser/dist/bundle/index.umd.min.js',out/'assets/passkeys.js')
    shutil.copy(root/'node_modules/@simplewebauthn/browser/LICENSE.md',out/'assets/passkeys.LICENSE.txt')
